#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// LinkLabel's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/link_label.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// Whether the link paints in its visited colour (Windows Forms' LinkVisited). Activation sets it; set it back to false if the target can become new again.
template <typename Declaring>
struct LinkLabelVisitedCapability {
    PropertyCell<bool, LinkLabelVisitedCapability<Declaring>> visited{};

    static void assign(LinkLabelVisitedCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.visited), incoming);
        if (!capability.visited.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.visited));
    }
};

// Every LinkLabel capability, in the order the declaring class takes them.
template <typename Declaring>
struct LinkLabelCapabilities : public LinkLabelVisitedCapability<Declaring> {};

} // namespace gui_forms
